using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.AI;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public static class B06OriginalPlay {
 static string Root=>Environment.GetEnvironmentVariable("UNITY_TEST_ROOT")??throw new Exception("explicit isolated save required");
 static CombatSession s;static Keyboard keyboard;static EditorWindow view;static double deadline,phaseTime,nextLog;static int phase;static float nextAttack,nextRoll;static Vector3 start;static NavMeshPath path=new NavMeshPath();static int corner;static Vector3 goal;static int alerted,returned;static bool capturedCombat;
 static void Need(bool b,string m){if(!b)throw new Exception(m);}
 public static void Run(){Directory.CreateDirectory(Root);deadline=EditorApplication.timeSinceStartup+180;ShaderUtil.allowAsyncCompilation=false;EditorSceneManager.OpenScene("Assets/CombatPrototype/ForestRuins.unity");EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Size(){var assembly=typeof(Editor).Assembly;Type sizesType=assembly.GetType("UnityEditor.GameViewSizes"),baseType=typeof(ScriptableSingleton<>).MakeGenericType(sizesType);object sizes=baseType.GetProperty("instance").GetValue(null);Type groupType=assembly.GetType("UnityEditor.GameViewSizeGroupType");object group=sizesType.GetMethod("GetGroup").Invoke(sizes,new[]{Enum.Parse(groupType,"Standalone")});Type sizeType=assembly.GetType("UnityEditor.GameViewSize"),modeType=assembly.GetType("UnityEditor.GameViewSizeType");object size=Activator.CreateInstance(sizeType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{Enum.Parse(modeType,"FixedResolution"),1280,720,"B06 normal AI"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});int index=(int)group.GetType().GetMethod("GetBuiltinCount").Invoke(group,null)+(int)group.GetType().GetMethod("GetCustomCount").Invoke(group,null)-1;view=EditorWindow.GetWindow(assembly.GetType("UnityEditor.GameView"));view.position=new Rect(20,20,1300,770);view.GetType().GetProperty("selectedSizeIndex",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(view,index);view.Show();view.Focus();}
 static void Capture(string label){ScreenCapture.CaptureScreenshot(Path.Combine(Root,label+".png"));}
 static void SetGoal(Vector3 p){goal=p;Need(NavMesh.SamplePosition(s.hero.transform.position,out var a,3,NavMesh.AllAreas)&&NavMesh.SamplePosition(p,out var b,3,NavMesh.AllAreas)&&NavMesh.CalculatePath(a.position,b.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete,"normal play route missing");corner=1;}
 static bool Walk(){while(corner<path.corners.Length-1&&Vector3.ProjectOnPlane(path.corners[corner]-s.hero.transform.position,Vector3.up).magnitude<1.5f)corner++;if(Vector3.ProjectOnPlane(goal-s.hero.transform.position,Vector3.up).magnitude<2){InputSystem.QueueStateEvent(keyboard,new KeyboardState());return true;}Vector3 dir=path.corners[corner]-s.hero.transform.position;s.orbit.RestoreView(Mathf.Atan2(dir.x,dir.z)*Mathf.Rad2Deg,28);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W,Key.LeftShift));return false;}
 static void Tick(){try{
 EditorApplication.QueuePlayerLoopUpdate();view?.Repaint();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("normal AI play timeout");if(!EditorApplication.isPlaying||Time.time<.4f)return;
 if(phase==0){s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();if(s==null)return;Size();InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;keyboard=InputSystem.AddDevice<Keyboard>();s.Saves.InitializeStorage(Path.Combine(Root,"test-save"),false);Need(s.Flow.Depart(AdventureMode.ForestExploration),"normal forest depart");start=s.hero.transform.position;SetGoal(s.GetComponent<ForestRegionRuntime>().Layout.points[1].position);phase=1;phaseTime=EditorApplication.timeSinceStartup;Capture("01-depart");return;}
 double now=EditorApplication.timeSinceStartup;if(now>nextLog){nextLog=now+1;var guards=s.enemies.Select(e=>e.GetComponent<EncounterGuard>()).Where(g=>g!=null).ToArray();alerted=Math.Max(alerted,guards.Count(g=>g.State==1));returned=Math.Max(returned,guards.Count(g=>g.State==2));File.AppendAllText(Path.Combine(Root,"normal-ai.csv"),$"{now:0.0},{phase},{s.hero.transform.position.x:0.0},{s.hero.transform.position.z:0.0},{s.hero.Health.Current:0.0},{guards.Count(g=>g.State==1)},{guards.Count(g=>g.State==2)},{s.enemies.Count(e=>e.Health.Dead)}\n");}
 if(s.hero.Progression.IsChoosing)s.hero.Progression.SelectChoice(0);
 if(s.Flow.HasResult){InputSystem.QueueStateEvent(keyboard,new KeyboardState());if(phase!=4){Capture("04-result");phase=4;phaseTime=now;return;}if(now-phaseTime<3)return;Need(s.Flow.CommitSettlement()&&s.Flow.AcknowledgeSettlement(),"normal camp commit");Need(s.Saves.SaveProgress(false)&&s.Saves.LoadProgress(false),"normal camp resume");Capture("05-camp");File.WriteAllText(Path.Combine(Root,"NORMAL_AI_RESULT.txt"),"Automated original-project play; all AI enabled, original health/damage/speeds, no teleports after departure.\nOutcome="+s.Flow.Settlement.outcome+"\nDistance="+Vector3.Distance(start,s.hero.transform.position)+"\nMax alerted="+alerted+" returning="+returned+"\nHuman play=NOT_RUN\n");phase=5;phaseTime=now;return;}
 if(phase==1){if(Walk()||s.hero.Health.Current<40||now-phaseTime>22){InputSystem.QueueStateEvent(keyboard,new KeyboardState());phase=2;phaseTime=now;Capture("02-encounter");}return;}
 if(phase==2){var nearest=s.enemies.Where(e=>!e.Health.Dead).OrderBy(e=>Vector3.Distance(e.transform.position,s.hero.transform.position)).FirstOrDefault();if(nearest!=null){var dir=nearest.transform.position-s.hero.transform.position;s.hero.transform.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(dir,Vector3.up));if(Time.time>nextAttack){nextAttack=Time.time+.6f;s.hero.Attack();}if(Time.time>nextRoll){nextRoll=Time.time+2.5f;s.hero.Dodge.TryDodge(-dir.normalized);}}if(!capturedCombat&&now-phaseTime>3){Capture("03-combat");capturedCombat=true;}if(now-phaseTime>12||s.hero.Health.Current<35){SetGoal(s.GetComponent<ForestRegionRuntime>().Layout.exits[0].position);phase=3;phaseTime=now;}return;}
 if(phase==3){if(Walk()){if(s.Flow.ActiveRun.phase==RunPhase.Running)s.Flow.BeginExtraction();if(s.Flow.ActiveRun.phase==RunPhase.Extracting&&now-phaseTime>3)Capture("03b-extraction");}return;}
 if(phase==5&&now-phaseTime>3){Debug.Log("B06_ORIGINAL_NORMAL_AI_PASS outcome="+s.Flow.Settlement.outcome+" alerted="+alerted+" returning="+returned);InputSystem.RemoveDevice(keyboard);EditorApplication.update-=Tick;EditorApplication.Exit(0);}
 }catch(Exception e){Debug.LogException(e);EditorApplication.update-=Tick;EditorApplication.Exit(1);}}
}
